draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw person
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // draw arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 - 30, H/2 + 50);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 + 30, H/2 + 50);
  ctx.stroke();

  // draw hands releasing
  ctx.beginPath();
  ctx.arc(W/2 - 30 + 10 * Math.sin(t), H/2 + 50, 5, 0, 2 * Math.PI);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W/2 + 30 + 10 * Math.sin(t), H/2 + 50, 5, 0, 2 * Math.PI);
  ctx.stroke();

  // draw bird flying away
  ctx.beginPath();
  ctx.arc(W/2 + 50 * Math.sin(t), H/2 - 20 - 20 * Math.cos(t), 10, 0, 2 * Math.PI);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + 50 * Math.sin(t), H/2 - 20 - 20 * Math.cos(t));
  ctx.lineTo(W/2 + 50 * Math.sin(t) + 10, H/2 - 20 - 20 * Math.cos(t) + 10);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + 50 * Math.sin(t), H/2 - 20 - 20 * Math.cos(t));
  ctx.lineTo(W/2 + 50 * Math.sin(t) - 10, H/2 - 20 - 20 * Math.cos(t) + 10);
  ctx.stroke();

  ctx.restore();
}
